import{_ as a,a as r,b as i,c as o}from"./chunks/presets-04.Dx-DqE4-.js";import{_ as e,o as n,c as s,a3 as l}from"./chunks/framework.D1iekJsc.js";const T=JSON.parse('{"title":"預設","description":"MiniTavern 提示詞預設：基礎提示詞和可排序的提示詞列表，切換角色扮演寫法；採樣參數仍在模型設定。","frontmatter":{"title":"預設","description":"MiniTavern 提示詞預設：基礎提示詞和可排序的提示詞列表，切換角色扮演寫法；採樣參數仍在模型設定。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"預設 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 提示詞預設：基礎提示詞和可排序的提示詞列表，切換角色扮演寫法；採樣參數仍在模型設定。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/manual/presets"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/manual/presets"}]]},"headers":[],"relativePath":"zh-TW/manual/presets.md","filePath":"zh-TW/manual/presets.md","lastUpdated":1791862671000}'),g={name:"zh-TW/manual/presets.md"};function p(c,t,h,m,d,u){return n(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="預設" tabindex="-1">預設 <a class="header-anchor" href="#預設" aria-label="Permalink to &quot;預設&quot;">​</a></h1><p>路徑：底部 <strong>設定</strong> → <strong>預設</strong>。</p><p>預設是一整套提示詞結構，用來改角色扮演的寫法和約束。溫度等採樣不在這裡，仍在 <strong>模型設定</strong>。</p><h2 id="步驟" tabindex="-1">步驟 <a class="header-anchor" href="#步驟" aria-label="Permalink to &quot;步驟&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+a+'" alt="設定裡的預設入口"><figcaption>1 · 設定 → 預設</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="預設列表"><figcaption>2 · 列表與新建</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="編輯預設"><figcaption>3 · Name、Basic prompts、Prompts</figcaption></figure><figure class="shot-step"><img src="'+o+'" alt="新建提示詞"><figcaption>4 · 新建提示詞</figcaption></figure></div><h2 id="列表" tabindex="-1">列表 <a class="header-anchor" href="#列表" aria-label="Permalink to &quot;列表&quot;">​</a></h2><ol><li>右上角 <strong>新建</strong> 可以選擇新建，或導入 SillyTavern Chat Completion 預設。導入時會忽略採樣參數，並提示到模型設定裡配置。</li><li>新安裝時只有帶 <strong>默認</strong> 標記的那一條。它不能編輯，也不能刪除。</li><li>一行右側的選單可以置頂、設為默認、編輯、複製、導出、刪除。</li><li>新建和複製都會先進入編輯頁，點 <strong>Save</strong> 之後才出現在列表裡。</li></ol><h2 id="編輯預設" tabindex="-1">編輯預設 <a class="header-anchor" href="#編輯預設" aria-label="Permalink to &quot;編輯預設&quot;">​</a></h2><p>編輯頁標題是 <strong>新建預設</strong> 或 <strong>編輯預設</strong>。部分欄位名稱目前是英文：</p><ul><li><strong>Name</strong> 必填。</li><li><strong>Basic prompts</strong> 裡可以改人設、角色描述、性格、場景、示例對話開頭、新對話開頭、世界書。</li><li><strong>Prompts</strong> 列表可以搜索。長按拖動排序。開關打開的會參與普通發送；關掉的進未激活，不再注入。</li><li>點 <strong>Add</strong> 進入新建提示詞。自訂條目可以編輯、複製、刪除。內建條目只能改名字和內容。</li></ul><p>角色卡上的主提示詞、歷史後指令會蓋過預設裡對應的條目。場景正文的優先級是：聊天設定，然後角色卡，最後才是預設基礎提示詞裡的純文字。</p><p>繼續、重新生成、智能回覆不讀這套預設。普通發送才會按列表順序拼進去。</p><h2 id="新建提示詞" tabindex="-1">新建提示詞 <a class="header-anchor" href="#新建提示詞" aria-label="Permalink to &quot;新建提示詞&quot;">​</a></h2><ol><li><strong>Name</strong> 必填。</li><li><strong>Role</strong> 預設是 SYSTEM，也可以改成別的角色。</li><li><strong>Injection position</strong> 選 <strong>Relative</strong> 時，這條插在列表裡的當前位置。選 <strong>In-chat</strong> 時才會出現 <strong>Injection depth</strong>，按深度插進歷史。</li><li><strong>Content</strong> 裡可以寫提示詞，也能用宏。</li><li>點 <strong>Save</strong> 回到預設編輯頁。</li></ol><h2 id="只改這一聊" tabindex="-1">只改這一聊 <a class="header-anchor" href="#只改這一聊" aria-label="Permalink to &quot;只改這一聊&quot;">​</a></h2><p>路徑：對話頁 → <strong>聊天設置</strong> → 模型 → <strong>預設</strong>。</p><p>默認跟隨默認預設。關掉之後，可以為這一聊另選一條，不影響其它對話。</p><h2 id="相關" tabindex="-1">相關 <a class="header-anchor" href="#相關" aria-label="Permalink to &quot;相關&quot;">​</a></h2><ul><li><a href="./model-link">模型連線</a>：採樣仍在模型設定</li><li><a href="./persona">人設</a> · <a href="./lorebook">世界書</a>：基礎提示詞裡會引用它們</li></ul>',19)])])}const v=e(g,[["render",p]]);export{T as __pageData,v as default};
